def blank(n): return [[0]*n for _ in range(n)]
def add_row_stripes(n, stripes):
    g=blank(n)
    for r,v in stripes.items(): g[r]=[v]*n
    return g
def add_diag(g, keyfn, k, v, rs=None):
    n=len(g)
    for r in range(n):
        for c in range(n):
            if keyfn(r,c)==k and (rs is None or r in rs): g[r][c]=v

def expected(n, keyfn, p, q):
    return [[q[keyfn(r,c)%p] for c in range(n)] for r in range(n)]

